<script setup lang="ts">
import {title as displayTitle,sourceName,indicator,utc,time as beijingTime,duration,http} from '../presentation/zh';
import {ref,onMounted} from 'vue';import {post,safeOfficialUrl} from '../api/client';
const props=defineProps<{token:string}>();type Row=Record<string,any>;
const tab=ref('金融原子事实'),facts=ref<Row[]>([]),legal=ref<Row[]>([]),requests=ref<Row>({}),reports=ref<Row[]>([]),selected=ref<Row>(),error=ref(''),busy=ref(false),page=ref(0),type=ref(''),search=ref(''),candidates=ref<Row[]>([]),lei=ref(''),snapshot=ref('');
const reviewDecision=ref('INSUFFICIENT'),reviewActor=ref(''),reviewReason=ref(''),reviewProof=ref(''),reviewQuote=ref(''),reviewHistory=ref<Row[]>([]);
async function reviewFact(){if(!selected.value?.id)return;await action(async()=>{await post('/facts/'+selected.value!.id+'/review',props.token,{decision:reviewDecision.value,actor:reviewActor.value,reason:reviewReason.value,evidenceId:reviewProof.value||selected.value!.evidence_id,excerpt:reviewQuote.value||selected.value!.excerpt});reviewHistory.value=await post<Row[]>('/facts/'+selected.value!.id+'/history',props.token);});}
const labels:Record<string,string>={EXTRACTED:'抽取候选',SOURCE_CHECKED:'官方来源确认',FIELD_MATCHED:'字段一致性通过',INDEPENDENT_SUPPORTED:'独立证据支持',CONFLICT:'证据冲突',REVISED:'已修订',INSUFFICIENT:'证据不足',REJECTED:'已驳回',OFFICIAL_PUBLICATION:'官方发布',MACRO_OBSERVATION:'宏观观测',DOCUMENT_REVISION:'资料修订',LEGAL_IDENTITY_ATTRIBUTE:'法人身份字段'};
const time=beijingTime;
async function action(work:()=>Promise<void>){busy.value=true;error.value='';try{await work();snapshot.value=new Date().toISOString();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){await action(async()=>{if(tab.value==='金融原子事实')facts.value=await post<Row[]>('/facts/query',props.token,{page:page.value,type:type.value});if(tab.value==='全球法人身份'){legal.value=await post<Row[]>('/entities/search',props.token,{search:'',page:0});requests.value=await post<Row>('/gleif/status',props.token);}if(tab.value==='金融事件研判')reports.value=await post<Row[]>('/impact/query',props.token,{page:page.value});});}
async function extract(){await action(async()=>{await post('/facts/extract',props.token,{limit:500});facts.value=await post<Row[]>('/facts/query',props.token,{page:0,type:type.value});});}
async function find(){await action(async()=>{const result=await post<Row>('/gleif/search',props.token,{name:search.value});candidates.value=result.candidates;});}
async function collect(){await action(async()=>{await post('/gleif/collect',props.token,{lei:lei.value});requests.value=await post<Row>('/gleif/status',props.token);legal.value=await post<Row[]>('/entities/search',props.token,{search:'',page:0});});}
async function detail(id:string){await action(async()=>{selected.value=await post<Row>('/entities/'+id,props.token);});}
async function analyze(fact:Row){await action(async()=>{selected.value=await post<Row>('/impact/analyze',props.token,{factId:fact.id,asOf:new Date().toISOString()});});}
onMounted(load);
</script>
<template><section class="panel fact-engine"><div class="section-title"><h2>全球金融事实引擎</h2><button :disabled="busy" @click="load">刷新实际数据</button></div><div class="tabs"><button v-for="name in ['金融原子事实','全球法人身份','金融事件研判']" :class="{primary:tab===name}" @click="tab=name;page=0;selected=undefined;load()">{{name}}</button></div><p>查询快照：<time :title="'UTC原值：'+utc(snapshot)">{{time(snapshot)}}</time> · 官方发布、字段一致性、独立核实与研判假设分别记录。</p><p v-if="error" role="alert">{{error}}</p>
<template v-if="tab==='金融原子事实'"><div class="filters"><select v-model="type" aria-label="事实类型" @change="page=0;load()"><option value="">全部事实类型</option><option value="MACRO_OBSERVATION">宏观观测</option><option value="OFFICIAL_PUBLICATION">官方发布</option><option value="LEGAL_IDENTITY_ATTRIBUTE">法人身份字段</option><option value="DOCUMENT_REVISION">资料修订</option></select><button :disabled="busy" @click="extract">从真实证据抽取</button></div><p v-if="!facts.length">暂无真实数据</p><article v-for="f in facts" :key="f.id" :data-fact-id="f.id"><div><b>{{labels[f.fact_type]||f.fact_type}}</b> <span class="badge">{{labels[f.effective_status||f.verification_status]||f.effective_status||f.verification_status}}</span></div><h3>{{f.fact_type==='LEGAL_IDENTITY_ATTRIBUTE'?'法人身份字段':indicator(f.fields.indicator_id)||displayTitle({source_id:f.source_id,original_title:f.fields.original_title}).text}}</h3><details v-if="f.fields.indicator_id"><summary>指标技术口径</summary><p>指标代码：{{f.fields.indicator_id}}</p></details><details v-if="f.fields.original_title"><summary>查看事实原文标题</summary><p class="original">{{f.fields.original_title}}</p></details><p v-if="f.fact_type==='MACRO_OBSERVATION'">观测期间 {{f.fields.observation_period}} · 实际值 {{f.fields.actual_value??'未提供'}} · 单位 {{f.fields.unit}} · 分母币种 {{f.fields.currency_denominator||'不适用'}} · 频率 {{({D:'日度',M:'月度',B:'工作日或政策变更日'} as Record<string,string>)[f.fields.frequency]||'按官方口径'}} · 版本 {{f.version}}</p><p>源发布时间：<time :title="'UTC原值：'+utc(f.available_at)">{{time(f.available_at,'官方发布时间未知')}}</time> · 实际采集：<time :title="'UTC原值：'+utc(f.collected_at)">{{time(f.collected_at)}}</time></p><p>{{f.fields.scope||f.fields.interpretation}}</p><button @click="selected=f">查看原始证据</button><button @click="analyze(f)">生成规则研判</button><a v-if="safeOfficialUrl(f.source_url)" :href="f.source_url" target="_blank" rel="noopener noreferrer">查看原始来源</a></article><div class="filters"><button :disabled="page===0||busy" @click="page--;load()">上一页</button><span>第 {{page+1}} 页 · 每页最多50条</span><button :disabled="facts.length<50||busy" @click="page++;load()">下一页</button></div></template>
<template v-if="tab==='全球法人身份'"><p>登记身份来自精确 LEI；名称搜索仅产生候选。未提供中文法人名称时保持原文。会计并表关系不等同供应链或股权比例。</p><div class="filters"><input v-model="search" placeholder="搜索官方法人名称"><button :disabled="busy||!search" @click="find">检索候选法人</button><input v-model="lei" placeholder="填写真实20位LEI"><button :disabled="busy||!lei" @click="collect">核验并保存法人</button></div><article v-for="c in candidates" :key="c.id"><b>{{c.attributes.entity.legalName.name}}</b><p>{{c.id}} · {{c.attributes.entity.jurisdiction}} · 检索候选</p><button @click="lei=c.id">选择此LEI供核验</button></article><p>保存法人版本 {{requests.records??'—'}} · 会计并表或报告例外版本 {{requests.level2??'—'}}</p><article v-for="e in legal.filter(e=>e.source_id==='GLEIF')" :key="e.id"><h3>{{e.chinese_name||'法人中文名称待核验'}}</h3><p class="original">官方法人名称：{{e.official_name}}</p><p>{{e.official_identifier}} · {{e.country}} · 法人登记字段确认</p><button @click="detail(e.id)">查看身份历史与证据</button></article></template>
<template v-if="tab==='金融事件研判'"><p>规则推断独立保存。证据截止时刻冻结；市场价格与收益验证尚未接入。</p><p v-if="!reports.length">暂无真实研判数据，请选择已有原子事实生成规则研判。</p><article v-for="r in reports" :key="r.id"><h3>{{r.report.summary||r.report.title}}</h3><p>规则 {{r.rule_id}} / {{r.rule_version}} · 证据截止 <time :title="'UTC原值：'+utc(r.as_of)">{{time(r.as_of)}}</time> · 生成 <time :title="'UTC原值：'+utc(r.created_at)">{{time(r.created_at)}}</time></p><button @click="selected=r">查看研判证据与局限</button></article><button :disabled="page===0" @click="page--;load()">上一页</button><button :disabled="reports.length<50" @click="page++;load()">下一页</button></template>
<div v-if="selected" class="fact-detail"><h3>证据与研判详情</h3><button @click="selected=undefined">关闭详情</button><template v-if="selected.excerpt"><p>{{selected.source_locator}}</p><pre>{{selected.excerpt}}</pre><p>SHA-256：{{selected.raw_content_hash}}</p><h4>事实人工审核</h4><select v-model="reviewDecision" aria-label="事实审核决定"><option value="INSUFFICIENT">证据不足</option><option value="CONFLICT">证据冲突</option><option value="REJECTED">驳回</option><option value="SOURCE_CHECKED">官方来源确认</option><option value="FIELD_MATCHED">维持已通过字段校验</option><option value="INDEPENDENT_SUPPORTED">独立来源支持（需人工同事实核对）</option></select><input v-model="reviewActor" placeholder="事实审核责任人"><input v-model="reviewProof" placeholder="补充真实证据编号（留空引用当前证据）"><textarea v-model="reviewQuote" placeholder="补充证据逐字摘录（留空引用当前摘录）"/><textarea v-model="reviewReason" placeholder="事实审核依据与局限（至少10字）"/><button @click="reviewFact">记录事实审核</button><article v-for="r in reviewHistory" :key="r.id"><p>{{labels[r.decision]}} · {{r.actor}} · <time :title="'UTC原值：'+utc(r.created_at)">{{time(r.created_at)}}</time></p><p>{{r.reason}}</p></article></template><template v-else-if="selected.profiles"><article v-for="p in selected.profiles" :key="p.id"><b>{{p.legal_name}}</b><p><time :title="'UTC原值：'+utc(p.created_at)">{{time(p.created_at)}}</time> · {{labels[p.latest_review]||'法人身份字段确认'}}</p><pre>{{p.excerpt}}</pre><a v-if="safeOfficialUrl(p.source_url)" :href="p.source_url" target="_blank" rel="noopener noreferrer">查看原始来源</a></article></template><template v-else-if="selected.report"><div v-for="(value,key) in selected.report" :key="key"><b>{{({summary:'事件摘要',source:'来源范围',integrity:'证据完整性',facts:'结构化事实',entities:'关联实体',industry:'关联产业',mechanism:'影响机制',positive:'正向假设',negative:'负向假设',counter_evidence:'反向证据',gaps:'证据缺口',watch_variables:'后续观察变量',validity:'适用与失效条件',market_status:'市场验证状态'} as Record<string,string>)[String(key)]||key}}</b><pre>{{typeof value==='string'?value:JSON.stringify(value,null,2)}}</pre></div></template></div>
</section></template>
<style scoped>.fact-engine{padding:20px;margin-bottom:20px;min-width:0}.tabs,.filters{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}article{padding:16px 0;border-bottom:1px solid #dce4ef}article button,article a{margin-right:12px}.badge{padding:4px 8px;border-radius:4px;background:#17353f;color:#7acdd0}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto;background:#0c1526;padding:14px}.fact-detail{border-top:2px solid #547a98;margin-top:18px}select,input{max-width:100%}p{line-height:1.7}</style>
